window.__votdWeek && window.__votdWeek({"week":"2028-07-10","reading":"Alma 30–31","days":[{"d":"2028-07-10","ref":"Alma 30:3","b":"Alma","c":30,"v":3,"he":"הֵן וְהָעָם שָׁמְרוּ לִשְׁמֹר אֶת־מִצְוֹת יְהוָה וַיֶּחֶרְדוּ לִשְׁמֹר אֶת־חֻקּוֹת אֱלֹהִים כְּפִי תּוֹרַת מֹשֶׁה כִּי לֻמְּדוּ לִשְׁמֹר אֶת־תּוֹרַת מֹשֶׁה עַד תִּמָּלֵא׃","en":"Yea, and the people did observe to keep the commandments of the Lord; and they were strict in observing the ordinances of God, according to the law of Moses; for they were taught to keep the law of Moses until it should be fulfilled."},{"d":"2028-07-11","ref":"Alma 30:7","b":"Alma","c":30,"v":7,"he":"וְלֹא־הָיָה חֹק נֶגֶד אֱמוּנַת אִישׁ כִּי הָיָה נֶגֶד מִצְוֹת אֱלֹהִים כִּי יִהְיֶה חֹק אֲשֶׁר יָבִיא אֲנָשִׁים לְבִלְתִּי הָיוֹת שָׁוִים׃","en":"Now there was no law against a man’s belief; for it was strictly contrary to the commands of God that there should be a law which should bring men on to unequal grounds."},{"d":"2028-07-12","ref":"Alma 30:49","b":"Alma","c":30,"v":49,"he":"וַיֹּאמֶר אַלְמָא אֵלָיו זֹאת אֶתֵּן־לְךָ לְאוֹת כִּי תֻכֶּה אִלֵּם כְּפִי דְבָרַי וַאֲנִי אוֹמֵר בְּשֵׁם אֱלֹהִים תֻכֶּה אִלֵּם וְלֹא־יִהְיֶה לְךָ עוֹד פִּתְחוֹן־פֶּה׃","en":"Now Alma said unto him: This will I give unto thee for a sign, that thou shalt be struck dumb, according to my words; and I say, that in the name of God, ye shall be struck dumb, that ye shall no more have utterance."},{"d":"2028-07-13","ref":"Alma 30:60","b":"Alma","c":30,"v":60,"he":"וְכֵן נִרְאֶה אֶת־אַחֲרִית מְעַקֵּשׁ דַּרְכֵי יְהוָה וְכֵן נִרְאֶה כִּי הַשָּׂטָן לֹא יַחֲזִיק בְּבָנָיו בַּיּוֹם הָאַחֲרוֹן כִּי־אִם בִּמְהֵרָה יְגוֹרֵם אֶל שְׁאוֹל׃","en":"And thus we see the end of him who perverteth the ways of the Lord; and thus we see that the devil will not support his children at the last day, but doth speedily drag them down to hell."},{"d":"2028-07-14","ref":"Alma 31:8","b":"Alma","c":31,"v":8,"he":"וְהַזּוֹרָמִים הָיוּ פּוֹרְשִׁים מִן־הַנֶּפִיִּים לָכֵן נִקְרָא לָהֶם דְּבַר־אֱלֹהִים מִלְּפָנִים׃","en":"Now the Zoramites were dissenters from the Nephites; therefore they had had the word of God preached unto them."},{"d":"2028-07-15","ref":"Alma 31:24","b":"Alma","c":31,"v":24,"he":"וַיְהִי כִּרְאוֹת אַלְמָא אֶת־זֹאת וַיֵּרַע לְבָבוֹ כִּי רָאָה כִּי עַם רָע וְעִקֵּשׁ הֵם אַף רָאָה כִּי לִבָּם נָתוּן לַזָּהָב וְלַכֶּסֶף וּלְכׇל־מִינֵי כְּלֵי חֶמְדָּה׃","en":"Now when Alma saw this his heart was grieved; for he saw that they were a wicked and a perverse people; yea, he saw that their hearts were set upon gold, and upon silver, and upon all manner of fine goods."},{"d":"2028-07-16","ref":"Alma 31:25","b":"Alma","c":31,"v":25,"he":"הֵן רָאָה גַם כִּי גָּבְהוּ לִבָּם לְהִתְהַלֵּל הַרְבֵּה בְּגַאֲוָתָם׃","en":"Yea, and he also saw that their hearts were lifted up unto great boasting, in their pride."}]});
